import {test,after} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {JSDOM} from 'jsdom';
import{projectTerrain,sampleTerrain}from'../terrain3d.mjs';
// Real DOM events and application state; canvas methods are stubbed because these
// tests verify editing/history behavior, not raster rendering or PNG encoding.
const dom=new JSDOM(await fs.readFile(new URL('../index.html',import.meta.url),'utf8'),{url:'https://example.test/'});
const w=dom.window,doc=w.document,$=id=>doc.getElementById(id);let blobs=[],symbols=0,strokes=0,draws=[],moves=[],shiftErase=false;
const canvasContext=new Proxy({createImageData:(x,y)=>({data:new Uint8ClampedArray(x*y*4)}),getImageData:(x,y,a,b)=>({data:new Uint8ClampedArray(a*b*4)}),drawImage:(...args)=>draws.push(args),moveTo:(...args)=>moves.push(args),translate:()=>{symbols++;},stroke:()=>{strokes++;}},{get:(o,k)=>k in o?o[k]:()=>{}});
w.HTMLCanvasElement.prototype.getContext=type=>type==='2d'?canvasContext:null;
w.HTMLCanvasElement.prototype.toBlob=function(cb){cb(new Blob(['image']));};
w.HTMLCanvasElement.prototype.setPointerCapture=()=>{};
w.HTMLAnchorElement.prototype.click=()=>{};
for(let id of['map','preview']){Object.defineProperty($(id),'clientWidth',{value:id==='map'?1024:224});Object.defineProperty($(id),'clientHeight',{value:id==='map'?768:165});}
Object.assign(globalThis,{requestAnimationFrame:cb=>{cb(performance.now());return 1;},document:doc,localStorage:w.localStorage,devicePixelRatio:1,ResizeObserver:class{observe(){}}});
const oldCreate=URL.createObjectURL,oldRevoke=URL.revokeObjectURL;
URL.createObjectURL=b=>{blobs.push(b);return'blob:test'};URL.revokeObjectURL=()=>{};
w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};
w.HTMLDialogElement.prototype.close=function(value){this.open=false;if(value!==undefined)this.returnValue=value;this.dispatchEvent(new w.Event('close'));};
await import('../app.mjs');
async function state(){blobs=[];$('save').click();return JSON.parse(await blobs[0].text());}
function key(key,more={}){doc.body.dispatchEvent(new w.KeyboardEvent('keydown',{key,bubbles:true,...more}));}
function pointer(type,x=512,y=380){$('map')['on'+type](new w.MouseEvent(type,{clientX:x,clientY:y,button:0,bubbles:true,shiftKey:shiftErase}));}
function clickTool(t){shiftErase=false;doc.querySelector(`[data-tool="${t}"]`).click();}
after(()=>{URL.createObjectURL=oldCreate;URL.revokeObjectURL=oldRevoke;});
test('Raise and Lower start gently while blend tools retain their strength and extremes remain available',()=>{assert.equal($('strength').value,'8');clickTool('lower');assert.equal($('strength').value,'8');clickTool('flatten');assert.equal($('strength').value,'35');clickTool('smooth');assert.equal($('strength').value,'35');clickTool('raise');$('strength').value='100';$('strength').dispatchEvent(new w.Event('input'));clickTool('lower');assert.equal($('strength').value,'100');clickTool('flatten');assert.equal($('strength').value,'35');clickTool('raise');assert.equal($('strength').value,'100');$('strength').value='8';$('strength').dispatchEvent(new w.Event('input'));});
test('resizing keys preserve active tool, and shift-wheel does not zoom',()=>{key('s');assert.equal($('size').value,'41');assert.ok(doc.querySelector('[data-tool="raise"]').classList.contains('selected'));key('W',{shiftKey:true});assert.equal($('size').value,'51');let zoom=$('zoomtext').textContent;$('map').dispatchEvent(new w.WheelEvent('wheel',{deltaY:-10,shiftKey:true,bubbles:true,cancelable:true}));assert.equal($('size').value,'52');assert.equal($('zoomtext').textContent,zoom);});
test('rejected JSON import preserves redo and project',async()=>{pointer('pointerdown');pointer('pointerup');$('undo').click();assert.equal($('redo').disabled,false);let before=await state();Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'bad.json',size:5,text:async()=>'{"version":2}'}]});await $('file').onchange();assert.equal($('redo').disabled,false);assert.deepEqual(await state(),before);});
test('switching tools during a stroke cannot edit locked relief',async()=>{doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();let before=await state();clickTool('paint');pointer('pointerdown');key('r');pointer('pointermove',530,390);pointer('pointerup');assert.deepEqual((await state()).heights,before.heights);doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();});
test('water toggle clears redo and can be independently undone',async()=>{clickTool('raise');pointer('pointerdown');pointer('pointerup');$('undo').click();assert.equal($('redo').disabled,false);const before=await state();$('water').click();assert.equal($('redo').disabled,true);$('undo').click();assert.equal((await state()).water,before.water);});
test('typing a name forms one undo group',async()=>{let before=await state();$('worldname').focus();$('worldname').value='The';$('worldname').dispatchEvent(new w.Event('input'));$('worldname').value='The Reach';$('worldname').dispatchEvent(new w.Event('input'));$('worldname').blur();assert.equal($('redo').disabled,true);$('undo').click();assert.equal((await state()).name,before.name);$('redo').click();assert.equal((await state()).name,'The Reach');});
test('Escape after reopening New world preserves project',async()=>{$('new').click();$('newdialog').close('generate');const before=await state();$('new').click();$('newdialog').close();assert.equal($('newdialog').returnValue,'');assert.deepEqual(await state(),before);});
// JSDOM does not implement dialog methods; this only models returnValue/event wiring.
test('opacity remains bounded over one paint stroke and builds over separate strokes',async()=>{clickTool('paint');$('opacity').value='25';pointer('pointerdown',550,400);for(let j=0;j<8;j++)pointer('pointermove',550,400);pointer('pointerup',550,400);let first=await state();assert.ok(Math.max(...first.paintAlpha)<=.2501);pointer('pointerdown',550,400);pointer('pointerup',550,400);let second=await state();assert.ok(Math.max(...second.paintAlpha)>.25&&Math.max(...second.paintAlpha)<=.438);$('opacity').value='100';});
test('workspace 3D orbit preserves the project and tool selection stays in 3D',async()=>{let before=await state();$('mode3d').click();assert.equal($('map').hidden,true);assert.equal($('preview').hidden,false);$('preview').onpointerdown(new w.MouseEvent('pointerdown',{clientX:100,clientY:100,button:2}));$('preview').onpointermove(new w.MouseEvent('pointermove',{clientX:120,clientY:110,button:2}));$('preview').onpointerup(new w.MouseEvent('pointerup',{clientX:120,clientY:110,button:2}));assert.deepEqual(await state(),before);clickTool('raise');assert.equal($('map').hidden,true);assert.equal($('preview').hidden,false);$('mode2d').click();});

test('zero opacity leaves paint, landmarks and drawings unchanged for opacity-driven tools',async()=>{$('opacity').value='0';let before=await state();for(let erasing of[false,true]){clickTool('paint');shiftErase=erasing;pointer('pointerdown',520,350);pointer('pointermove',600,400);pointer('pointerup',600,400);}assert.deepEqual(await state(),before);$('opacity').value='100';});
test('undo during a held brush gesture stops subsequent edits and preserves redo',async()=>{clickTool('paint');let before=await state();pointer('pointerdown',500,300);pointer('pointermove',570,350);key('z',{ctrlKey:true});assert.ok(JSON.stringify(await state())===JSON.stringify(before),'Project should remain at the restored state');pointer('pointermove',620,400);pointer('pointerup',620,400);assert.ok(JSON.stringify(await state())===JSON.stringify(before),'Project should remain at the restored state');assert.equal($('redo').disabled,false);$('redo').click();assert.notDeepEqual((await state()).paintAlpha,before.paintAlpha);});

function worldScreen(x,y,s){let camera={yaw:-.65,pitch:.65,zoom:1,panX:0,panY:0},height=sampleTerrain(x,y,s.heights,s.sea,s.water);return projectTerrain(x,y,height,224,165,camera);}
function event3(type,p,more={}){$('preview')['on'+type](new w.MouseEvent(type,{clientX:p.x,clientY:p.y,button:0,bubbles:true,shiftKey:shiftErase,...more}));}
test('all sculpt tools edit terrain directly in the 3D workspace',async()=>{$('mode3d').click();$('orbit-reset').click();$('opacity').value='100';$('strength').value='100';$('target').value='20';for(let tool of['raise','lower','smooth','flatten']){clickTool(tool);let before=await state(),p=worldScreen(140,140,before);event3('pointerdown',p);event3('pointerup',p);let after=await state();assert.ok(JSON.stringify(after.heights)!==JSON.stringify(before.heights),tool+' should alter terrain');assert.equal($('map').hidden,true);}});
test('surface paint and coastline removal work in 3D',async()=>{clickTool('paint');doc.querySelector('[data-material="5"]').click();let before=await state(),p=worldScreen(170,130,before);event3('pointerdown',p);event3('pointerup',p);assert.ok(JSON.stringify((await state()).paintColors)!==JSON.stringify(before.paintColors));clickTool('land');before=await state();p=worldScreen(140,140,before);event3('pointerdown',p,{shiftKey:true});event3('pointerup',p,{shiftKey:true});assert.ok(JSON.stringify((await state()).heights)!==JSON.stringify(before.heights));});
test('selecting an editing tool exits Orbit mode without leaving 3D',()=>{$('mode3d').click();$('orbit-toggle').click();assert.equal($('orbit-toggle').getAttribute('aria-pressed'),'true');clickTool('paint');assert.equal($('orbit-toggle').getAttribute('aria-pressed'),'false');assert.equal($('map').hidden,true);$('mode2d').click();});
test('Canvas fallback reduces draw work while orbiting and restores full detail on release',()=>{$('mode3d').click();$('preview').onpointerdown(new w.MouseEvent('pointerdown',{clientX:100,clientY:100,button:2}));strokes=0,draws=[],moves=[];$('preview').onpointermove(new w.MouseEvent('pointermove',{clientX:110,clientY:105,button:2}));let moving=strokes;strokes=0,draws=[],moves=[];$('preview').onpointerup(new w.MouseEvent('pointerup',{clientX:110,clientY:105,button:2}));assert.ok(strokes>moving*3,'Full detail should return after orbit ends');$('mode2d').click();});
function eraseTarget(value){clickTool('paint');shiftErase=true;$('erase-target').value=value;$('erase-target').dispatchEvent(new w.Event('change'));}
test('Erase surface paint reveals base color without altering terrain and supports undo',async()=>{$('mode2d').click();clickTool('paint');$('opacity').value='100';pointer('pointerdown',550,400);pointer('pointerup',550,400);let before=await state();assert.equal(doc.querySelector('[data-tool="erase"]'),null);eraseTarget('surface');pointer('pointerdown',550,400);pointer('pointerup',550,400);let after=await state();assert.ok(after.paintAlpha.reduce((a,b)=>a+b,0)<before.paintAlpha.reduce((a,b)=>a+b,0));assert.deepEqual(after.heights,before.heights);$('undo').click();assert.deepEqual((await state()).paintAlpha,before.paintAlpha);});
test('eraser respects the selected layer lock',async()=>{eraseTarget('surface');doc.querySelector('[data-layer="surface"][data-action="locked"]').click();let before=await state();pointer('pointerdown',550,400);pointer('pointerup',550,400);assert.deepEqual((await state()).paintAlpha,before.paintAlpha);doc.querySelector('[data-layer="surface"][data-action="locked"]').click();});
test('the surface eraser works directly in 3D',async()=>{$('mode3d').click();$('orbit-reset').click();clickTool('paint');let s=await state(),p=worldScreen(170,130,s);event3('pointerdown',p);event3('pointerup',p);let before=await state();eraseTarget('surface');event3('pointerdown',p);event3('pointerup',p);let after=await state();assert.ok(after.paintAlpha.reduce((a,b)=>a+b,0)<before.paintAlpha.reduce((a,b)=>a+b,0));assert.deepEqual(after.heights,before.heights);assert.equal($('map').hidden,true);$('mode2d').click();});
test('toolbox collapse keeps tools available and exposes a settings flyout',async()=>{let before=await state();$('collapse-sidebar').click();assert.ok(doc.body.classList.contains('sidebar-collapsed'));assert.equal($('collapse-sidebar').getAttribute('aria-expanded'),'false');assert.equal(doc.querySelectorAll('[data-tool]').length,9);$('rail-settings').click();assert.ok(doc.body.classList.contains('tool-settings-open'));key('Escape');assert.equal(doc.body.classList.contains('tool-settings-open'),false);$('collapse-sidebar').click();assert.equal(doc.body.classList.contains('sidebar-collapsed'),false);assert.deepEqual(await state(),before);});
test('toolbox resize supports pointer and keyboard with persisted bounds',()=>{let handle=$('sidebar-resizer');handle.setPointerCapture=()=>{};handle.onpointerdown(new w.MouseEvent('pointerdown',{clientX:228,button:0}));handle.onpointermove(new w.MouseEvent('pointermove',{clientX:600,button:0}));handle.onpointerup();assert.equal(handle.getAttribute('aria-valuenow'),'360');handle.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Home'}));assert.equal(handle.getAttribute('aria-valuenow'),'180');handle.dispatchEvent(new w.KeyboardEvent('keydown',{key:'ArrowRight'}));assert.equal(handle.getAttribute('aria-valuenow'),'190');assert.equal(JSON.parse(w.localStorage.getItem('landwright-ui')).sidebarWidth,190);});
test('light and dark preferences persist without modifying project data',async()=>{let before=await state();$('theme-toggle').click();assert.equal(doc.documentElement.dataset.theme,'light');assert.equal(JSON.parse(w.localStorage.getItem('landwright-ui')).theme,'light');$('theme-toggle').click();assert.equal(doc.documentElement.dataset.theme,'dark');assert.deepEqual(await state(),before);});
test('Flatten UI protects map edges by default and allows explicitly unlocking them',async()=>{clickTool('flatten');$('strength').value='100';$('target').value='120';$('opacity').value='100';assert.equal($('preserve-edges').checked,true);const scale=Math.min((1024-70)/256,(768-135)/256),x=(1024-256*scale)/2+2*scale,y=(768-256*scale)/2-6+128*scale;let before=await state();for(let j=0;j<10;j++){pointer('pointerdown',x,y);pointer('pointerup',x,y);}let after=await state();for(let i=0;i<256;i++){assert.equal(after.heights[i],before.heights[i]);assert.equal(after.heights[i*256],before.heights[i*256]);assert.equal(after.heights[i*256+255],before.heights[i*256+255]);assert.equal(after.heights[255*256+i],before.heights[255*256+i]);}$('preserve-edges').checked=false;pointer('pointerdown',x,y);pointer('pointerup',x,y);assert.ok((await state()).heights[128*256]>after.heights[128*256]);$('preserve-edges').checked=true;});
test('new flat worlds use selected grid sizes and undo restores previous size',async()=>{const before=await state();assert.ok($('world-size'));for(let n of[128,192,256]){$('new').click();$('world-size').value=String(n);doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');let s=await state();assert.equal(s.size,n);assert.equal(s.heights.length,n*n);assert.ok(s.heights.every(h=>h===80));assert.ok(s.paint.every(p=>p===0));assert.equal($('map-dimensions').textContent,`${n} × ${n}`);$('undo').click();assert.deepEqual(await state(),before);}});
test('small project save/import preserves size and edits after 3D reset',async()=>{$('new').click();$('world-size').value='128';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');const saved=await state();$('new').click();$('world-size').value='256';$('newdialog').close('generate');Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'small.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual(await state(),saved);$('mode3d').click();$('orbit-reset').click();clickTool('raise');let c={yaw:-.65,pitch:.65,zoom:1,size:128},p=projectTerrain(64,64,80,224,165,c);for(let type of['pointerdown','pointerup'])$('preview')['on'+type](new w.MouseEvent(type,{clientX:p.x,clientY:p.y,button:0,bubbles:true}));assert.ok((await state()).heights.some(h=>h>80));$('mode2d').click();});
test('Coastline and Sand combine without switching tools or altering elevation',async()=>{$('new').click();$('world-size').value='256';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');clickTool('paint');doc.querySelector('[data-brush="coast"]').click();assert.equal(doc.querySelector('[data-tool="paint"]').getAttribute('aria-pressed'),'true');doc.querySelector('[data-material="2"]').click();assert.equal(doc.querySelector('[data-brush="coast"]').getAttribute('aria-pressed'),'true');const before=await state();pointer('pointerdown');pointer('pointerup');let after=await state();assert.deepEqual(after.heights,before.heights);assert.ok(after.paint.some(x=>x===2));assert.equal(after.marks.length,0);clickTool('raise');clickTool('paint');assert.equal(doc.querySelector('[data-brush="coast"]').getAttribute('aria-pressed'),'true');});
test('brushes and materials never select another tool; brush menus stay visible',()=>{assert.equal(doc.querySelector('[data-brush="forest"]'),null);assert.ok(doc.querySelector('[data-brush="hard"]'));for(let tool of['raise','paint','pan']){clickTool(tool);for(let brush of['soft','coast','hard']){let b=doc.querySelector(`[data-brush="${brush}"]`);if(!b.disabled)b.click();assert.equal(doc.querySelector(`[data-tool="${tool}"]`).getAttribute('aria-pressed'),'true');}doc.querySelector('[data-material="2"]').click();assert.equal(doc.querySelector(`[data-tool="${tool}"]`).getAttribute('aria-pressed'),'true');assert.equal($('brush-settings').hidden,false);assert.equal($('palette-section').hidden,tool!=='paint');assert.equal($('brush-controls').hidden,false);}});
test('all three footprints paint Sand in 3D without modifying relief or landmarks',async()=>{$('mode3d').click();$('orbit-reset').click();clickTool('paint');$('opacity').value='100';doc.querySelector('[data-material="2"]').click();for(let brush of['soft','hard','coast']){doc.querySelector(`[data-brush="${brush}"]`).click();const before=await state();let p=worldScreen(128,128,before);event3('pointerdown',p);event3('pointerup',p);const after=await state();assert.ok(after.paint.some(x=>x===2),brush);assert.notDeepEqual(after.paintAlpha,before.paintAlpha,brush);assert.deepEqual(after.heights,before.heights);assert.deepEqual(after.marks,before.marks);$('undo').click();} });
test('Drawing and Details are removed from toolbar, settings, and keyboard shortcuts',async()=>{assert.equal(doc.querySelector('[data-tool="draw"]'),null);assert.equal(doc.querySelector('[data-tool="stamp"]'),null);assert.equal($('drawing-settings'),null);assert.equal($('stamp-settings'),null);clickTool('paint');let before=await state();for(let k of['d','D','t','T']){key(k);assert.equal(doc.querySelector('[data-tool="paint"]').getAttribute('aria-pressed'),'true');}assert.deepEqual(await state(),before);assert.equal(doc.querySelectorAll('[data-tool]').length,9);});
test('new maps show only terrain layers and surface erasing',async()=>{$('new').click();$('newdialog').close('generate');assert.equal(doc.querySelectorAll('.layer-row').length,2);assert.deepEqual([...$('erase-target').options].map(o=>o.value),['surface']);});
test('legacy drawings and landmarks survive import, terrain edits, undo, and export',async()=>{const {makeShape}=await import('../shapes.mjs');let project=await state();project.marks=[{type:'tree',x:128,y:128,size:10,opacity:1}];project.shapes=[makeShape('line',{x:120,y:120},{x:140,y:140},{color:'#123456',width:2,opacity:1,filled:false},false,256)];Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'legacy.json',size:100,text:async()=>JSON.stringify(project)}]});await $('file').onchange();assert.deepEqual((await state()).marks,project.marks);assert.deepEqual((await state()).shapes,project.shapes);assert.equal(doc.querySelectorAll('.layer-row').length,4);assert.deepEqual([...$('erase-target').options].map(o=>o.value),['surface','landmarks','shapes']);$('mode2d').click();clickTool('paint');pointer('pointerdown');pointer('pointerup');$('undo').click();assert.deepEqual((await state()).marks,project.marks);assert.deepEqual((await state()).shapes,project.shapes);symbols=strokes=0,draws=[],moves=[];$('export-map').click();assert.ok(symbols>0&&strokes>0);doc.querySelector('[data-layer="landmarks"][data-action="visible"]').click();doc.querySelector('[data-layer="shapes"][data-action="visible"]').click();symbols=strokes=0,draws=[],moves=[];$('export-map').click();assert.equal(symbols,0);assert.equal(strokes,0);});
test('starting fresh after legacy erasing restores surface eraser controls',()=>{eraseTarget('landmarks');assert.equal($('opacity').disabled,false);$('new').click();$('newdialog').close('generate');assert.equal($('erase-target').value,'surface');assert.equal($('opacity').disabled,false);assert.match($('erase-description').textContent,/natural terrain/);});
test('erasing the last legacy mark never changes target mid-gesture and refreshes controls on release',async()=>{let project=await state();project.marks=[{type:'tree',x:128,y:128,size:10,opacity:1}];project.paintAlpha.fill(1);project.paint.fill(1);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'legacy.json',size:100,text:async()=>JSON.stringify(project)}]});await $('file').onchange();eraseTarget('landmarks');pointer('pointerdown');assert.equal($('erase-target').value,'landmarks');pointer('pointermove',520,380);let during=await state();assert.equal(during.marks.length,0);assert.deepEqual(during.paintAlpha,project.paintAlpha);pointer('pointerup',520,380);assert.equal($('erase-target').value,'surface');assert.equal($('opacity').disabled,false);assert.match($('erase-description').textContent,/natural terrain/);$('undo').click();assert.deepEqual((await state()).marks,project.marks);});
function routeClick(x,y){pointer('pointerdown',x,y);pointer('pointerup',x,y);}
test('path preview cancels without mutations and commits dirt as one undoable route',async()=>{$('mode2d').click();$('new').click();$('world-size').value='256';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');clickTool('path');let before=await state();routeClick(450,350);pointer('pointermove',520,380);assert.equal($('brush').style.display,'none');routeClick(600,400);key('Escape');assert.deepEqual(await state(),before);routeClick(450,350);routeClick(600,400);key('Enter');let after=await state();assert.equal(after.routes.length,1);assert.equal(after.routes[0].type,'path');assert.ok(after.paint.some(v=>v===6));assert.deepEqual(after.heights,before.heights);$('undo').click();assert.deepEqual(await state(),before);$('redo').click();assert.deepEqual((await state()).routes,after.routes);});
test('river carving above sea level preserves ocean settings and saves with undo',async()=>{clickTool('river');$('route-width').value='8';$('river-depth').value='5';let before=await state();routeClick(460,330);routeClick(580,420);$('finish-route').click();let after=await state();assert.equal(after.routes.length,before.routes.length+1);assert.equal(after.routes.at(-1).type,'river');assert.ok(after.routes.at(-1).points.every(p=>p.level>62));assert.ok(after.heights.some((h,i)=>h<before.heights[i]));assert.equal(after.sea,before.sea);assert.equal(after.water,before.water);$('undo').click();assert.deepEqual(await state(),before);$('redo').click();assert.deepEqual((await state()).routes,after.routes);});
test('hidden or locked terrain blocks river commit; switching tools cancels a draft',async()=>{let before=await state();clickTool('river');routeClick(450,330);routeClick(600,400);clickTool('paint');assert.deepEqual(await state(),before);doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();clickTool('river');routeClick(450,330);routeClick(600,400);key('Enter');assert.deepEqual((await state()).heights,before.heights);doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();});
test('path and river place in 3D and river water erasing preserves the bed',async()=>{$('mode3d').click();$('orbit-reset').click();clickTool('path');$('path-material').value='2';let before=await state();for(let p of[worldScreen(90,90,before),worldScreen(140,95,before)]){event3('pointerdown',p);event3('pointerup',p);}$('finish-route').click();let after=await state();assert.equal(after.routes.length,before.routes.length+1);assert.equal(after.routes.at(-1).material,2);assert.deepEqual(after.heights,before.heights);clickTool('river');for(let p of[worldScreen(90,110,after),worldScreen(140,115,after)]){event3('pointerdown',p);event3('pointerup',p);}$('preview').ondblclick(new w.MouseEvent('dblclick',{cancelable:true}));let river=await state();assert.equal(river.routes.at(-1).type,'river');assert.ok(river.heights.some((h,i)=>h<after.heights[i]));eraseTarget('rivers');const {riverField,waterSurface}=await import('../routes.mjs');let surface=waterSurface(Float32Array.from(river.heights),riverField(river.routes,256),true),height=sampleTerrain(115,112.5,surface,river.sea,true),p=projectTerrain(115,112.5,height,224,165,{yaw:-.65,pitch:.65,zoom:1});event3('pointerdown',p);event3('pointerup',p);let erased=await state();assert.ok(erased.routes.length<river.routes.length);assert.deepEqual(erased.heights,river.heights);$('undo').click();assert.deepEqual((await state()).routes,river.routes);$('mode2d').click();});
test('routes survive project import and a rejected route leaves the current project and history intact',async()=>{let before=await state();Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'routes.json',size:100,text:async()=>JSON.stringify(before)}]});await $('file').onchange();assert.deepEqual(await state(),before);let bad=structuredClone(before);bad.routes[0].points[0].x=Infinity;Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'bad.json',size:100,text:async()=>JSON.stringify(bad)}]});await $('file').onchange();assert.deepEqual(await state(),before);});
test('click-only routes do not create history; route width shortcuts and mode changes respect drafts',async()=>{clickTool('path');let before=await state();routeClick(450,350);key('Enter');assert.deepEqual(await state(),before);$('route-width').value='8';key('w');assert.equal($('route-width').value,'9');routeClick(600,400);$('mode3d').click();$('finish-route').click();assert.deepEqual(await state(),before);$('mode2d').click();});
test('dragging a route from outside the map cannot create an empty draft or throw',async()=>{clickTool('path');let before=await state();assert.doesNotThrow(()=>{pointer('pointerdown',10,10);pointer('pointermove',500,350);pointer('pointerup',500,350);});$('finish-route').click();assert.deepEqual(await state(),before);key('Escape');});
test('middle-drag pans a 2D route draft without adding a route point',async()=>{key('Escape');$('fit').click();clickTool('path');routeClick(512,378);routeClick(600,400);const wantX=(600-195.5)/(633/256),wantY=(400-61.5)/(633/256);$('map').onpointerdown(new w.MouseEvent('pointerdown',{clientX:300,clientY:300,button:1}));$('map').onpointermove(new w.MouseEvent('pointermove',{clientX:400,clientY:450,button:1}));$('map').onpointerup(new w.MouseEvent('pointerup',{clientX:400,clientY:450,button:1}));key('Enter');let p=(await state()).routes.at(-1).points.at(-1);assert.ok(Math.abs(p.x-wantX)<.001&&Math.abs(p.y-wantY)<.001);$('fit').click();});
test('undo during a held route gesture cancels it and cannot fall through to terrain sculpting',async()=>{for(let type of['path','river']){clickTool(type);const before=await state();pointer('pointerdown',450,350);pointer('pointermove',550,380);key('z',{ctrlKey:true});pointer('pointermove',620,420);pointer('pointerup',620,420);assert.ok(JSON.stringify(await state())===JSON.stringify(before),'Cancelling a held route must preserve the complete project');assert.equal($('route-bar').hidden,true);}});

test('palette and opacity are contextual; sculpting ignores paint opacity',()=>{for(let tool of['raise','lower','smooth','flatten','land','pan','path','river']){clickTool(tool);assert.equal($('palette-section').hidden,true,tool);}clickTool('paint');assert.equal($('palette-section').hidden,false);assert.equal($('opacity-label').hidden,false);for(let tool of['raise','lower','smooth','flatten','land','pan']){clickTool(tool);assert.equal($('opacity-label').hidden,true,tool);}clickTool('path');assert.equal($('opacity-label').hidden,false);clickTool('paint');assert.equal($('opacity-label').hidden,false);});
