test('river taper and meander controls persist taper without affecting Path or tool count',async()=>{clickTool('river');assert.ok($('river-taper').checked);assert.equal($('river-meander').value,'25');let before=await state();routeClick(450,350);routeClick(600,400);$('finish-route').click();let saved=await state();assert.equal(saved.version,8);assert.equal(saved.routes.at(-1).taper,true);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'taper.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual((await state()).routes,saved.routes);clickTool('path');assert.equal($('river-taper-label').hidden,true);assert.equal($('river-meander-label').hidden,true);assert.equal(doc.querySelectorAll('[data-tool]').length,9);});
test('reflow rivers is one undo group, recuts wet channels, leaves paths and ocean unchanged, and respects locks',async()=>{let s=await state();assert.ok(s.routes.some(r=>r.type==='river'));const before=structuredClone(s);$('reflow-rivers').click();let after=await state();assert.equal(after.sea,before.sea);assert.deepEqual(after.routes.filter(r=>r.type==='path'),before.routes.filter(r=>r.type==='path'));assert.ok(after.routes.filter(r=>r.type==='river').some((r,i)=>r.points.some((p,j)=>p.level!==before.routes.filter(r=>r.type==='river')[i].points[j].level)));$('undo').click();assert.ok(JSON.stringify(await state())===JSON.stringify(before));$('redo').click();assert.ok(JSON.stringify(await state())===JSON.stringify(after));doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();const locked=await state();assert.equal($('reflow-rivers').disabled,true);$('reflow-rivers').click();assert.ok(JSON.stringify(await state())===JSON.stringify(locked));doc.querySelector('[data-layer="elevation"][data-action="locked"]').click();});
test('Living World settings are visual preferences and never alter project data or undo history',async()=>{let before=await state(),undoDisabled=$('undo').disabled;assert.ok($('living-toggle'));$('living-toggle').click();$('living-clouds').checked=false;$('living-clouds').dispatchEvent(new w.Event('change'));assert.ok(JSON.stringify(await state())===JSON.stringify(before));assert.equal($('undo').disabled,undoDisabled);assert.equal(JSON.parse(w.localStorage.getItem('landwright-living')).clouds,false);$('living-vegetation').checked=false;$('living-vegetation').dispatchEvent(new w.Event('change'));assert.equal(JSON.parse(w.localStorage.getItem('landwright-living')).vegetationMotion,false);assert.ok(JSON.stringify(await state())===JSON.stringify(before));assert.equal(doc.querySelectorAll('[data-tool]').length,9);});

test('Forest paints density with a stable tool, target density and opacity-once-per-stroke; undo restores ground',async()=>{$('mode2d').click();$('new').click();$('world-size').value='128';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');clickTool('paint');doc.querySelector('[data-material="4"]').click();assert.equal($('forest-settings').hidden,false);assert.equal(doc.querySelector('[data-tool="paint"]').getAttribute('aria-pressed'),'true');doc.querySelector('[data-brush="hard"]').click();$('forest-density').value='80';$('opacity').value='50';let before=await state();pointer('pointerdown');for(let j=0;j<12;j++)pointer('pointermove');pointer('pointerup');let after=await state();assert.equal(after.version,8);assert.ok(Math.abs(Math.max(...after.forest)-.4)<.0001);assert.deepEqual(after.paintAlpha,before.paintAlpha);assert.deepEqual(after.heights,before.heights);assert.ok(doc.querySelector('[data-layer="forests"]'));assert.ok([...$('erase-target').options].some(o=>o.value==='forests'));$('undo').click();assert.deepEqual((await state()).forest,before.forest);$('redo').click();assert.deepEqual((await state()).forest,after.forest);assert.equal(doc.querySelectorAll('[data-tool]').length,9);});
test('Forest erase honors opacity and its own locks while preserving surface color; Shift Forest clears',async()=>{clickTool('paint');doc.querySelector('[data-material="2"]').click();$('opacity').value='100';pointer('pointerdown');pointer('pointerup');let before=await state();eraseTarget('forests');assert.equal($('opacity').disabled,false);doc.querySelector('[data-layer="forests"][data-action="locked"]').click();pointer('pointerdown');pointer('pointerup');assert.deepEqual((await state()).forest,before.forest);doc.querySelector('[data-layer="forests"][data-action="locked"]').click();$('opacity').value='50';pointer('pointerdown');pointer('pointerup');let cleared=await state();assert.ok(cleared.forest.reduce((a,b)=>a+b,0)<before.forest.reduce((a,b)=>a+b,0));assert.deepEqual(cleared.paintAlpha,before.paintAlpha);assert.deepEqual(cleared.heights,before.heights);clickTool('paint');doc.querySelector('[data-material="4"]').click();$('opacity').value='100';$('map').onpointerdown(new w.MouseEvent('pointerdown',{clientX:512,clientY:380,button:0,shiftKey:true}));pointer('pointerup');assert.ok((await state()).forest.every(v=>v===0));assert.equal($('erase-target').value,'forests');});
test('Forest edits work in 3D, survive project import, reject malformed imports without losing redo, and clear on new world',async()=>{clickTool('paint');doc.querySelector('[data-material="4"]').click();$('mode3d').click();$('orbit-reset').click();let before=await state(),p=projectTerrain(64,64,80,224,165,{yaw:-.65,pitch:.65,zoom:1,size:128});event3('pointerdown',p);event3('pointerup',p);let saved=await state();assert.ok(saved.forest.some(v=>v>0));assert.deepEqual(saved.heights,before.heights);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'forest.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual((await state()).forest,saved.forest);$('undo').click();let restored=await state();assert.equal($('redo').disabled,false);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'badforest.json',size:100,text:async()=>JSON.stringify({...saved,forest:[2]})}]});await $('file').onchange();assert.equal($('redo').disabled,false);assert.ok(JSON.stringify(await state())===JSON.stringify(restored));$('mode2d').click();$('new').click();$('newdialog').close('generate');assert.ok((await state()).forest.every(v=>v===0));});
test('stopping a Forest stroke with Escape retains edits and reconciles conditional layer/erase controls',async()=>{$('mode2d').click();$('new').click();$('world-size').value='128';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');clickTool('paint');doc.querySelector('[data-material="4"]').click();doc.querySelector('[data-brush="hard"]').click();$('forest-density').value='100';$('opacity').value='100';pointer('pointerdown');key('Escape');assert.ok((await state()).forest.some(v=>v>0));assert.ok(doc.querySelector('[data-layer="forests"]'));assert.ok([...$('erase-target').options].some(o=>o.value==='forests'));eraseTarget('forests');pointer('pointerdown');key('Escape');assert.ok((await state()).forest.every(v=>v===0));assert.equal(doc.querySelector('[data-layer="forests"]'),null);assert.equal($('erase-target').value,'forests');});
test('3D woodland rendering preserves legacy landmark order in project data',async()=>{let s=await state();s.marks=[{type:'town',x:110,y:110,size:9,opacity:1},{type:'tree',x:5,y:5,size:9,opacity:1}];Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'legacyorder.json',size:100,text:async()=>JSON.stringify(s)}]});await $('file').onchange();$('mode3d').click();$('orbit-reset').click();assert.deepEqual((await state()).marks,s.marks);$('mode2d').click();});

function flatSettlementWorld(){$('mode2d').click();$('new').click();$('world-size').value='128';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');}
function releaseSpace(){doc.body.dispatchEvent(new w.KeyboardEvent('keyup',{key:' ',code:'Space',bubbles:true}));}
test('settlement creation controls are removed from the sidebar',()=>{assert.equal($('settlement-panel'),null);assert.equal(doc.querySelector('[id="settlement-place"]'),null);assert.equal(doc.querySelectorAll('[data-tool]').length,9);});
test('Space left-drag pans 2D without editing or changing the tool; keyup resumes sculpting',async()=>{flatSettlementWorld();$('fit').click();clickTool('raise');const before=await state();draws=[];key(' ',{code:'Space'});pointer('pointerdown');pointer('pointermove',572,410);pointer('pointerup',572,410);releaseSpace();assert.deepEqual(await state(),before);assert.equal(doc.querySelector('[data-tool="raise"]').getAttribute('aria-pressed'),'true');const mapDraw=draws.filter(a=>a.length===5&&Math.abs(a[3]-633)<.01).at(-1);assert.ok(mapDraw);assert.ok(Math.abs(mapDraw[1]-(195.5+60))<.01);pointer('pointerdown');pointer('pointerup');assert.notDeepEqual((await state()).heights,before.heights);});
test('Space left-drag pans 3D even off terrain, without orbiting or editing',async()=>{flatSettlementWorld();$('mode3d').click();$('orbit-reset').click();clickTool('raise');const before=await state();moves=[];key(' ',{code:'Space'});event3('pointerdown',{x:0,y:0});let initial=moves[0];moves=[];event3('pointermove',{x:60,y:30});let shifted=moves[0];event3('pointerup',{x:60,y:30});releaseSpace();assert.ok(initial&&shifted);assert.ok(Math.abs(shifted[0]-initial[0]-60)<.01);assert.ok(Math.abs(shifted[1]-initial[1]-30)<.01);assert.deepEqual(await state(),before);$('mode2d').click();});
test('Space typing does not capture pan, and blur clears held Space',async()=>{flatSettlementWorld();clickTool('raise');$('worldname').dispatchEvent(new w.KeyboardEvent('keydown',{key:' ',code:'Space',bubbles:true}));const before=await state();pointer('pointerdown');pointer('pointerup');assert.notDeepEqual((await state()).heights,before.heights);key(' ',{code:'Space'});w.dispatchEvent(new w.Event('blur'));const next=await state();pointer('pointerdown');pointer('pointerup');assert.notDeepEqual((await state()).heights,next.heights);releaseSpace();});

test('saved settlements survive import, terrain editing, undo and export after panel removal',async()=>{flatSettlementWorld();let saved=await state();saved.settlements=[{id:'keep',kind:'hamlet',x:64,y:64,scale:1,rotation:0,seed:42,name:'Old Town'}];Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'places.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual((await state()).settlements,saved.settlements);clickTool('raise');pointer('pointerdown',400,400);pointer('pointerup',400,400);$('undo').click();assert.deepEqual((await state()).settlements,saved.settlements);$('mode3d').click();$('mode2d').click();assert.deepEqual((await state()).settlements,saved.settlements);});
test('Space pan does not append route points or destroy its preview',async()=>{flatSettlementWorld();clickTool('path');pointer('pointerdown',400,350);pointer('pointerup',400,350);key(' ',{code:'Space'});pointer('pointerdown',500,380);pointer('pointermove',560,410);releaseSpace();pointer('pointermove',570,420);pointer('pointerup',570,420);assert.equal((await state()).routes.length,0);key('Escape');assert.equal((await state()).routes.length,0);});

test('D/E adjust opacity by five points, clamp, and preserve tool and project',async()=>{clickTool('paint');$('opacity').value='50';const before=await state();key('d');assert.equal($('opacity').value,'45');key('e');assert.equal($('opacity').value,'50');assert.equal($('opacityout').value,'50%');for(let i=0;i<30;i++)key('D');assert.equal($('opacity').value,'0');for(let i=0;i<30;i++)key('E');assert.equal($('opacity').value,'100');assert.equal(doc.querySelector('[data-tool="paint"]').getAttribute('aria-pressed'),'true');assert.deepEqual(await state(),before);});
test('Erase is removed from the toolbar and E no longer selects a tool',()=>{assert.equal(doc.querySelector('[data-tool="erase"]'),null);assert.equal(doc.querySelectorAll('[data-tool]').length,9);clickTool('raise');$('opacity').value='50';key('e');assert.equal($('opacity').value,'50');assert.equal(doc.querySelector('[data-tool="raise"]').getAttribute('aria-pressed'),'true');});
test('opacity shortcuts respect typing and dialogs',()=>{clickTool('paint');$('opacity').value='50';$('worldname').dispatchEvent(new w.KeyboardEvent('keydown',{key:'e',bubbles:true}));assert.equal($('opacity').value,'50');$('help').click();key('d');assert.equal($('opacity').value,'50');$('helpdialog').close();});

test('Path D/E opacity changes affect the committed route without selecting another tool',async()=>{flatSettlementWorld();clickTool('path');$('opacity').value='50';key('d');pointer('pointerdown',400,350);pointer('pointerup',400,350);pointer('pointerdown',600,350);pointer('pointerup',600,350);key('Enter');const s=await state();assert.equal(s.routes.length,1);assert.equal(s.routes[0].opacity,.45);assert.equal(doc.querySelector('[data-tool="path"]').getAttribute('aria-pressed'),'true');});
test('Shift erases whole saved objects at zero paint opacity and undo restores them',async()=>{flatSettlementWorld();const s=await state();s.settlements=[{id:'shift',kind:'hamlet',x:64,y:64,scale:1,rotation:0,seed:7,name:'Keep'}];Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'places.json',size:100,text:async()=>JSON.stringify(s)}]});await $('file').onchange();eraseTarget('settlements');$('opacity').value='0';pointer('pointerdown');pointer('pointerup');const erased=await state();assert.equal(erased.settlements.length,0);assert.deepEqual(erased.heights,s.heights);$('undo').click();assert.deepEqual((await state()).settlements,s.settlements);});

test('New World previews shape and detail without modifying the current map',async()=>{const before=await state();$('new').click();assert.equal($('newdialog').getAttribute('aria-labelledby'),'new-world-title');$('world-size').value='192';$('world-size').dispatchEvent(new w.Event('change'));doc.querySelector('[data-shape="flat"]').click();assert.equal($('world-preview').width,192);assert.match($('new-world-summary').textContent,/192 × 192/);assert.match($('shape-description').textContent,/level|flat/i);assert.match($('world-size-help').textContent,/export/i);$('newdialog').close('cancel');assert.deepEqual(await state(),before);});
test('New World offers an editable backup without creating a map',async()=>{const before=await state();$('new').click();blobs=[];$('backup-world').click();assert.equal($('newdialog').open,true);assert.deepEqual(JSON.parse(await blobs[0].text()),before);$('newdialog').close('cancel');});
test('map export resolutions change image dimensions without changing terrain or project',async()=>{const before=await state();const original=w.HTMLCanvasElement.prototype.toBlob;const sizes=[];w.HTMLCanvasElement.prototype.toBlob=function(cb){sizes.push([this.width,this.height]);cb(new Blob(['image']));};try{for(const n of[1024,2048,4096]){$('export').click();$('export-size').value=String(n);$('export-size').dispatchEvent(new w.Event('change'));assert.match($('export-map-size').textContent,new RegExp(String(n)));$('export-map').click();assert.deepEqual(sizes.at(-1),[n,n]);assert.deepEqual(await state(),before);}$('export').click();$('export-height').click();assert.deepEqual(sizes.at(-1),[before.size,before.size]);}finally{w.HTMLCanvasElement.prototype.toBlob=original;}});

test('earthen palette groups eight ground materials and keeps Forest separate with three footprints',()=>{clickTool('paint');assert.deepEqual([...doc.querySelectorAll('#palette [data-material]')].map(e=>+e.dataset.material),[1,6,7,3,8,9,2,5]);assert.equal(doc.querySelectorAll('#palette .material-family').length,5);assert.ok(doc.querySelector('#forest-paint [data-material="4"]'));assert.equal(doc.querySelector('[data-brush="grain"]'),null);assert.equal(doc.querySelectorAll('[data-brush]').length,3);assert.equal(doc.querySelectorAll('[data-tool]').length,9);});
test('earthen material coverage paints, mixes once per stroke, erases, and restores through undo',async()=>{flatSettlementWorld();clickTool('paint');doc.querySelector('[data-brush="hard"]').click();$('opacity').value='50';doc.querySelector('[data-material="7"]').click();const before=await state();pointer('pointerdown');for(let i=0;i<5;i++)pointer('pointermove');pointer('pointerup');const clay=await state();assert.equal(clay.version,8);assert.ok(clay.surfaceMaterials.length>0);let bytes=Uint8Array.from(atob(clay.surfaceMaterials),c=>c.charCodeAt(0)),cell=64*128+64;assert.ok(bytes[cell*8+5]>=127&&bytes[cell*8+5]<=128);assert.deepEqual(clay.heights,before.heights);assert.deepEqual(clay.forest,before.forest);doc.querySelector('[data-material="8"]').click();pointer('pointerdown');pointer('pointerup');const mixed=await state();bytes=Uint8Array.from(atob(mixed.surfaceMaterials),c=>c.charCodeAt(0));assert.ok(bytes[cell*8+5]>0&&bytes[cell*8+6]>0);$('undo').click();assert.equal((await state()).surfaceMaterials,clay.surfaceMaterials);$('redo').click();assert.equal((await state()).surfaceMaterials,mixed.surfaceMaterials);eraseTarget('surface');$('opacity').value='100';pointer('pointerdown');pointer('pointerup');const erased=await state();bytes=erased.surfaceMaterials?Uint8Array.from(atob(erased.surfaceMaterials),c=>c.charCodeAt(0)):new Uint8Array(128*128*8);assert.ok([...bytes.slice(cell*8,cell*8+8)].every(v=>v===0));assert.deepEqual(erased.heights,before.heights);});
test('old blended paint and legacy palette RGB survive migration; malformed material coverage preserves world and redo',async()=>{flatSettlementWorld();let legacy=await state();legacy.version=6;delete legacy.surfaceMaterials;legacy.paint[0]=3;legacy.paintAlpha[0]=.37;legacy.paintColors.splice(0,3,101,118,137);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'oldpaint.json',size:100,text:async()=>JSON.stringify(legacy)}]});await $('file').onchange();const migrated=await state();assert.equal(migrated.version,8);assert.equal(migrated.surfaceMaterials,'');assert.deepEqual(migrated.paintColors,legacy.paintColors);assert.deepEqual(migrated.paintAlpha,legacy.paintAlpha);$('undo').click();const before=await state();assert.equal($('redo').disabled,false);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'badcoverage.json',size:100,text:async()=>JSON.stringify({...migrated,surfaceMaterials:'not-base64!'})}]});await $('file').onchange();assert.deepEqual(await state(),before);assert.equal($('redo').disabled,false);});
test('all eight earthen materials paint in 3D without changing terrain or forest density',async()=>{flatSettlementWorld();$('mode3d').click();$('orbit-reset').click();clickTool('paint');$('opacity').value='100';const before=await state();for(let id of[1,6,7,3,8,9,2,5]){doc.querySelector(`[data-material="${id}"]`).click();let p=projectTerrain(64,64,80,224,165,{yaw:-.65,pitch:.65,zoom:1,size:128});event3('pointerdown',p);event3('pointerup',p);const s=await state();assert.equal(s.paint[64*128+64],id);assert.deepEqual(s.heights,before.heights);assert.deepEqual(s.forest,before.forest);}assert.ok((await state()).surfaceMaterials.length>0);$('mode2d').click();});

test('Flatten D/E adjust target height precisely without editing terrain or strength',async()=>{clickTool('raise');$('strength').value='8';$('strength').dispatchEvent(new w.Event('input'));clickTool('flatten');$('target').value='120';const before=await state(),strength=$('strength').value,opacity=$('opacity').value;key('d');assert.equal($('target').value,'119');key('e');assert.equal($('target').value,'120');key('E',{shiftKey:true});assert.equal($('target').value,'130');key('D',{shiftKey:true});assert.equal($('target').value,'120');$('target').value='254';key('E',{shiftKey:true});assert.equal($('target').value,'255');$('target').value='2';key('D',{shiftKey:true});assert.equal($('target').value,'1');assert.equal($('targetout').value,'1');assert.equal($('strength').value,strength);assert.equal($('opacity').value,opacity);assert.deepEqual(await state(),before);$('worldname').dispatchEvent(new w.KeyboardEvent('keydown',{key:'e',bubbles:true}));assert.equal($('target').value,'1');$('help').click();key('e');assert.equal($('target').value,'1');$('helpdialog').close();key('e',{ctrlKey:true});key('e',{metaKey:true});key('e',{altKey:true});assert.equal($('target').value,'1');key('e');assert.equal($('target').value,'2');clickTool('raise');key('e');assert.equal($('target').value,'2');assert.equal($('strength').value,'8');});

test('settlement paint preview is transient and commits one exact saved layout with one Undo',async()=>{flatSettlementWorld();clickTool('paint');assert.ok($('paint-places'));$('paint-places').click();assert.equal(doc.querySelectorAll('[data-place-kind]').length,5);assert.equal(doc.querySelectorAll('[data-tool]').length,9);$('size').value='42';const before=await state();pointer('pointerdown');pointer('pointermove',545,380);pointer('pointerup',545,380);assert.deepEqual(await state(),before);assert.equal($('commit-place').disabled,false);$('commit-place').click();const placed=await state();assert.equal(placed.version,8);assert.equal(placed.settlements.length,1);assert.equal(placed.settlements[0].kind,'village');assert.ok(placed.settlements[0].layout.buildings.length>0);assert.deepEqual(placed.heights,before.heights);assert.deepEqual(placed.paintColors,before.paintColors);assert.deepEqual(placed.forest,before.forest);$('undo').click();assert.deepEqual(await state(),before);$('redo').click();assert.deepEqual((await state()).settlements,placed.settlements);clickTool('raise');pointer('pointerdown');pointer('pointerup');assert.deepEqual((await state()).settlements,placed.settlements);$('undo').click();$('paint-ground').click();});
test('settlement preview cancels safely and layer locks block placement',async()=>{flatSettlementWorld();clickTool('paint');$('paint-places').click();pointer('pointerdown');pointer('pointerup');const before=await state();key('Escape');assert.equal($('commit-place').disabled,true);assert.deepEqual(await state(),before);pointer('pointerdown');pointer('pointerup');clickTool('flatten');assert.equal($('commit-place').disabled,true);clickTool('paint');pointer('pointerdown');pointer('pointerup');$('paint-ground').click();assert.equal($('commit-place').disabled,true);$('paint-places').click();pointer('pointerdown');pointer('pointerup');doc.querySelector('[data-layer="settlements"][data-action="locked"]').click();const locked=await state();$('commit-place').click();assert.deepEqual(await state(),locked);doc.querySelector('[data-layer="settlements"][data-action="locked"]').click();key('Escape');$('paint-ground').click();});
test('settlement brush places in3D, survives import, and rejects malformed stored geometry atomically',async()=>{flatSettlementWorld();clickTool('paint');$('paint-places').click();doc.querySelector('[data-place-kind="abbey"]').click();$('mode3d').click();$('orbit-reset').click();let p=projectTerrain(64,64,80,224,165,{yaw:-.65,pitch:.65,zoom:1,size:128});event3('pointerdown',p);event3('pointerup',p);assert.equal($('commit-place').disabled,false);key('Enter');let saved=await state();assert.equal(saved.settlements.length,1);assert.equal(saved.settlements[0].kind,'abbey');const original=structuredClone(saved.settlements);Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'places.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual((await state()).settlements,original);saved.settlements[0].layout.buildings[0].corners[0].x=1e8;const before=await state();Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'bad-place.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual(await state(),before);$('mode2d').click();$('paint-ground').click();});

test('sea changes invalidate a settlement draft and Enter from its name commits only a reviewed preview',async()=>{flatSettlementWorld();clickTool('paint');$('paint-places').click();doc.querySelector('[data-place-kind="village"]').click();pointer('pointerdown');pointer('pointerup');assert.equal($('commit-place').disabled,false);$('sea').value='100';$('sea').dispatchEvent(new w.Event('input'));assert.equal($('commit-place').disabled,true);key('Enter');assert.equal((await state()).settlements.length,0);$('sea').value='62';$('sea').dispatchEvent(new w.Event('input'));assert.equal($('commit-place').disabled,false);$('place-name').value='Bendhaven';$('place-name').dispatchEvent(new w.Event('input'));$('place-name').dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true}));assert.equal((await state()).settlements[0].name,'Bendhaven');pointer('pointerdown',650,380);pointer('pointerup',650,380);$('place-name').dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal($('cancel-place').disabled,true);$('paint-ground').click();});

test('edited settlement names sanitize pasted controls and remain reloadable',async()=>{flatSettlementWorld();clickTool('paint');$('paint-places').click();doc.querySelector('[data-place-kind="village"]').click();pointer('pointerdown');pointer('pointerup');$('place-name').value='Hill\tFort';$('place-name').dispatchEvent(new w.Event('input'));$('commit-place').click();const saved=await state();assert.equal(saved.settlements[0].name,'Hill Fort');Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'named-place.json',size:100,text:async()=>JSON.stringify(saved)}]});await $('file').onchange();assert.deepEqual((await state()).settlements,saved.settlements);$('paint-ground').click();});
